#Generated by ChatGPT

import time

import cv2
from ultralytics import YOLO

from vision_core.core.config import (
    YOLO_MODEL_WEIGHTS,
    CONFIDENCE_THRESHOLD,
    DEVICE
)
from vision_core.detection.detector import YOLODetector


image_path = (
    r"C:\Users\abdel\Downloads\mvtec_5_categories\bottle\test\broken_large\000.png"
)

frame = cv2.imread(image_path)

assert frame is not None

model = YOLO(YOLO_MODEL_WEIGHTS)

detector = YOLODetector(
    model=model,
    confidence_threshold=float(CONFIDENCE_THRESHOLD),
    device=DEVICE
)


# Warm-up
for _ in range(5):
    detector.predict(frame)


# Benchmark
latencies = []

for _ in range(20):

    start = time.perf_counter()

    detector.predict(frame)

    end = time.perf_counter()

    latency = (end - start) * 1000

    latencies.append(latency)


average_latency = sum(latencies) / len(latencies)
min_latency = min(latencies)
max_latency = max(latencies)

fps = 1000 / average_latency


print(f"Average latency: {average_latency:.2f} ms")
print(f"Min latency:     {min_latency:.2f} ms")
print(f"Max latency:     {max_latency:.2f} ms")
print(f"FPS:             {fps:.2f}")